/* =========================================================
   Sugarcane GIS — My Farm (farmer PWA)
   Single-page app: hash router + fetch calls to the real
   backend, falling back to DEMO data when offline or the
   backend isn't reachable (so the UI is always previewable).
========================================================= */

const state = {
  farmer: null,
  parcel: null,
  parcels: [], // summary list, for the switcher
  ndvi: null,
  harvest: null,
  alerts: [],
  boundaryCapture: [], // points captured this session, before save (edit existing boundary)
  newParcel: { points: [], method: "gps_walk", variety: "", planting_date: "" }, // Add Parcel draft
  usingDemo: false,
  clientFarmDemo: false
};

// ---------- API wrapper ----------
async function api(path, opts = {}) {
  if (state.clientFarmDemo && opts.method && !["GET", "HEAD"].includes(opts.method.toUpperCase()) && path !== "/farmer/logout") {
    toast("This client farm preview is read-only.");
    return null;
  }
  try {
    const res = await fetch(path, {
      credentials: "include",
      headers: { "Content-Type": "application/json" },
      ...opts
    });
    if (!res.ok) throw new Error("HTTP " + res.status);
    state.usingDemo = false;
    return await res.json();
  } catch (err) {
    state.usingDemo = true;
    return null; // caller decides the demo fallback shape
  }
}

async function loadFarmerData() {
  const me = await api("/farmer/api/me");
  state.farmer = me?.farmer || DEMO.farmer;
  if (me?.farmer && new URLSearchParams(location.search).get("client-preview") === "1" && typeof CLIENT_FARM_DATA !== "undefined") {
    state.clientFarmDemo = true;
    state.parcels = CLIENT_FARM_DATA.parcels;
    state.parcel = CLIENT_FARM_DATA.parcelDetails["Makina"];
    state.ndvi = { current: null, status: "Not supplied", trend: [] };
    state.harvest = { status: "Not supplied", days_to_harvest: null, estimated_yield: null, harvest_date: null, history: [] };
    state.alerts = [];
    state.usingDemo = false;
    return;
  }
  state.parcel = me?.parcel || DEMO.parcel;
  const ndvi = await api(`/farmer/api/parcel/${state.parcel.Parcel_ID}/ndvi`);
  state.ndvi = ndvi || DEMO.ndvi;
  const harvest = await api(`/farmer/api/parcel/${state.parcel.Parcel_ID}/harvest`);
  state.harvest = harvest || DEMO.harvest;
  const alerts = await api("/farmer/api/alerts");
  state.alerts = alerts || DEMO.alerts;
  const parcels = await api("/farmer/api/parcels");
  state.parcels = parcels || [state.parcel];
}

async function switchParcel(id) {
  if (state.clientFarmDemo) {
    const selected = CLIENT_FARM_DATA.parcelDetails[id];
    if (!selected) return;
    state.parcel = selected;
    state.ndvi = { current: null, status: "Not supplied", trend: [] };
    state.harvest = { status: "Not supplied", days_to_harvest: null, estimated_yield: null, harvest_date: null, history: [] };
    go("/farm");
    return;
  }
  const p = await api(`/farmer/api/parcel/${id}`);
  if (p) state.parcel = p;
  const ndvi = await api(`/farmer/api/parcel/${id}/ndvi`);
  if (ndvi) state.ndvi = ndvi;
  const harvest = await api(`/farmer/api/parcel/${id}/harvest`);
  if (harvest) state.harvest = harvest;
  go("/farm");
}

// ---------- Router ----------
const routes = {
  "/home": viewHome,
  "/farm": viewFarm,
  "/map": viewMap,
  "/route": viewRoute,
  "/harvest": viewHarvest,
  "/ndvi": viewNdvi,
  "/alerts": viewAlerts,
  "/parcel": viewParcelDetails,
  "/parcels": viewParcelsList,
  "/add-parcel": viewAddParcel,
  "/update-info": viewUpdateInfo,
  "/profile": viewProfile
};

function currentPath() {
  return location.hash.replace("#", "") || "/home";
}

async function render() {
  const path = currentPath();
  const fn = routes[path] || viewHome;
  document.getElementById("app").innerHTML = await fn();
  highlightNav(path);
  afterRender(path);
}

function highlightNav(path) {
  document.querySelectorAll(".bottom-nav button").forEach((b) => {
    b.classList.toggle("active", b.dataset.path === path);
  });
}

window.addEventListener("hashchange", render);

// ---------- Shared chrome ----------
function bottomNav(active) {
  const tabs = [
    { path: "/home", icon: "🏠", label: "Home" },
    { path: "/map", icon: "🗺️", label: "Map" },
    { path: "/harvest", icon: "🌾", label: "Harvest" },
    { path: "__more", icon: "☰", label: "More" }
  ];
  return `
  <div class="bottom-nav">
    ${tabs
      .map(
        (t) => `
      <button data-path="${t.path}" class="${active === t.path ? "active" : ""}"
        onclick="${t.path === "__more" ? "openMoreSheet()" : `go('${t.path}')`}">
        <span class="nav-icon">${t.icon}</span>${t.label}
      </button>`
      )
      .join("")}
  </div>`;
}

function go(path) {
  location.hash = "#" + path;
}

function openMoreSheet() {
  const sheet = document.createElement("div");
  sheet.className = "sheet-backdrop";
  sheet.onclick = (e) => { if (e.target === sheet) sheet.remove(); };
  sheet.innerHTML = `
    <div class="sheet">
      <div class="grip"></div>
      <div class="sheet-item" onclick="go('/ndvi');this.closest('.sheet-backdrop').remove();">
        <span class="ic">🌿</span> Crop Health (NDVI)
      </div>
      <div class="sheet-item" onclick="go('/alerts');this.closest('.sheet-backdrop').remove();">
        <span class="ic">🔔</span> Alerts & Notifications
      </div>
      <div class="sheet-item" onclick="go('/update-info');this.closest('.sheet-backdrop').remove();">
        <span class="ic">📝</span> Update Farm Information
      </div>
      <div class="sheet-item" onclick="go('/add-parcel');this.closest('.sheet-backdrop').remove();">
        <span class="ic">➕</span> Add a Parcel
      </div>
      <div class="sheet-item" onclick="go('/parcels');this.closest('.sheet-backdrop').remove();">
        <span class="ic">📋</span> My Parcels
      </div>
      <div class="sheet-item" onclick="go('/route');this.closest('.sheet-backdrop').remove();">
        <span class="ic">🚗</span> Route to Parcel
      </div>
      <div class="sheet-item" onclick="go('/profile');this.closest('.sheet-backdrop').remove();">
        <span class="ic">👤</span> Profile
      </div>
      <div class="sheet-item" onclick="logout();">
        <span class="ic">🚪</span> Logout
      </div>
    </div>`;
  document.body.appendChild(sheet);
}

function toast(msg) {
  const t = document.createElement("div");
  t.className = "toast";
  t.textContent = msg;
  document.body.appendChild(t);
  setTimeout(() => t.remove(), 2600);
}

function demoNote() {
  if (state.clientFarmDemo) return `<p class="small muted center-text mt-8">Client preview · five surveyed boundaries shown. Crop, yield and NDVI records were not supplied.</p>`;
  return state.usingDemo
    ? `<p class="small muted center-text mt-8">Showing demo data — connect the backend to see your live farm.</p>`
    : "";
}

// ---------- Gauge / sparkline helpers ----------
function ndviGauge(value) {
  if (value == null || !Number.isFinite(Number(value))) return `<div class="gauge"><div class="center"><strong>—</strong><span>Not supplied</span></div></div>`;
  value = Number(value);
  const pct = Math.max(0, Math.min(1, value));
  const r = 40, c = 2 * Math.PI * r;
  const offset = c * (1 - pct);
  const color = pct >= 0.6 ? "#2E7D32" : pct >= 0.4 ? "#FB8C00" : "#E53935";
  return `
  <div class="gauge">
    <svg width="96" height="96" viewBox="0 0 96 96">
      <circle cx="48" cy="48" r="${r}" stroke="#E5E7EB" stroke-width="9" fill="none"/>
      <circle cx="48" cy="48" r="${r}" stroke="${color}" stroke-width="9" fill="none"
        stroke-linecap="round" stroke-dasharray="${c}" stroke-dashoffset="${offset}"/>
    </svg>
    <div class="center">
      <strong>${value.toFixed(2)}</strong>
      <span>${pct >= 0.6 ? "Healthy" : pct >= 0.4 ? "Fair" : "Stressed"}</span>
    </div>
  </div>`;
}

function sparkline(points, height = 60) {
  const vals = points.map((p) => p.value);
  const min = 0, max = 1;
  const w = 220;
  const step = w / (points.length - 1 || 1);
  const coords = points
    .map((p, i) => {
      const x = i * step;
      const y = height - ((p.value - min) / (max - min)) * height;
      return `${x},${y}`;
    })
    .join(" ");
  return `
  <svg viewBox="0 0 ${w} ${height}" width="100%" height="${height}" preserveAspectRatio="none">
    <polyline points="${coords}" fill="none" stroke="#2E7D32" stroke-width="2.5"/>
    ${points
      .map((p, i) => {
        const x = i * step, y = height - ((p.value - min) / (max - min)) * height;
        return `<circle cx="${x}" cy="${y}" r="3" fill="#2E7D32"/>`;
      })
      .join("")}
  </svg>`;
}

